import { readFileSync, realpathSync } from 'node:fs';
import { join, relative } from 'node:path';
import { verifyHotfixRuntimeInventory, verifyHotfixRuntimeModule } from './hotfix-runtime-inventory.ts';

function json(path: string): any { return JSON.parse(readFileSync(path, 'utf8')); }
export function hotfixModuleOrigin(modulePath: string, diagnostic?: (reason: string) => void, admitted?: (checkModule: (path: string) => void) => void): string | undefined {
  const marker = modulePath.indexOf('/raf-hotfix/generations/');
  if (marker < 0) return undefined;
  const control = modulePath.slice(0, marker) + '/raf-hotfix';
  try {
    const state = json(join(control, 'registry.json'));
    for (const [root, generation] of Object.entries(state.generations ?? {}) as [string, any][]) {
      if (!modulePath.startsWith(root + '/')) continue;
      if (!root.startsWith(join(control, 'generations') + '/') || generation.root !== root || realpathSync(root) !== root || !['src', 'bin', 'scripts'].includes(relative(root, modulePath).split('/')[0])) return undefined;
      verifyHotfixRuntimeInventory(root, generation.commit, generation.runtimeInventory, modulePath);
      admitted?.(path => verifyHotfixRuntimeModule(root, generation.commit, generation.runtimeInventory, path));
      return root;
    }
  } catch (error) { diagnostic?.(error instanceof Error ? error.message : String(error)); }
  return undefined;
}

}
function currentFiles(root: string, policy: Pick<HotfixRuntimePolicy, 'scopes' | 'rootFiles' | 'excludedTrees'>, directories?: { path: string; mode: number }[]): HotfixRuntimeFile[] {
  if (!isAbsolute(root) || resolve(root) !== root || realpathSync(root) !== root || !lstatSync(root).isDirectory()) refused('noncanonical generation root');
  const entries = readdirSync(root, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name));
  const declared = new Set([...policy.scopes, ...policy.rootFiles, ...policy.excludedTrees]);
  for (const item of entries) {
    const entry = item.name;
    if (entry === '.git') continue;
    if (policy.excludedTrees.includes(entry)) {
      if (!item.isDirectory()) refused('excluded area alias/type changed ' + entry);
      continue;
    }
    if (!declared.has(entry)) refused('unknown root input ' + entry);
    const info = checkedInfo(root, entry);
    if (policy.rootFiles.includes(entry) ? !info.isFile() : !info.isDirectory()) refused('search area type changed ' + entry);
  }
  const files: HotfixRuntimeFile[] = [];
  function walk(path: string): void {
    const info = checkedInfo(root, path);
    if (info.isDirectory()) {
      directories?.push({ path, mode: info.mode & 0o777 });
      for (const name of readdirSync(join(root, path)).sort()) walk(path + '/' + name);
    }
    else files.push({ path, sha256: digest(readFileSync(join(root, path))), mode: info.mode & 0o777 });
  }
  for (const path of [...policy.scopes, ...policy.rootFiles].sort()) walk(path);
  return files.sort((a, b) => a.path < b.path ? -1 : a.path > b.path ? 1 : 0);
}
