import { readFileSync, realpathSync, statSync } from 'node:fs';
import { basename, dirname, join, resolve, sep } from 'node:path';
import { userInfo } from 'node:os';
import { commandFailure, failureContext } from './cli-contract.ts';

export function resolveStateContext(request: StateContextRequest): StateContext {
  const orchestratorRoot = canonicalStatePath(resolve(request.orchestratorRoot));
  const modulePath = canonicalStatePath(resolve(request.modulePath));
  const codeRoot = moduleCodeRoot(modulePath);
  const settingsPath = join(orchestratorRoot, 'conf', 'raf.json');
  let settings;
  try { settings = JSON.parse(readFileSync(settingsPath, 'utf8')); }
  catch (error) { contextFailure('CONFIGURATION_INVALID', `Cannot read valid ${settingsPath}: ${error instanceof Error ? error.message : String(error)}`, settingsPath); }
  const fileName = settings?.state?.fileName;
  if (settings?.version !== 1 || typeof fileName !== 'string' || !fileName.trim() || ['.', '..'].includes(fileName) ||
      basename(fileName) !== fileName || /[\\/\0]/.test(fileName)) contextFailure('CONFIGURATION_INVALID', `Invalid raf.json version or state.fileName: ${settingsPath}`, settingsPath);
  const workingHome = canonicalStatePath(request.operatingSystemHome);
  const selectedHome = canonicalStatePath(request.homeDirectory);
  const mode: StateContext['mode'] = request.environment.RAF_QA_HOME ? 'qa' : 'production';
  const statePath = join(selectedHome, '.raf', fileName);
  if (mode === 'production' && selectedHome === workingHome && request.entryPoint === 'cli') {
    const productionRoot = configuredProductionRoot(orchestratorRoot);
    if (productionRoot && !inside(modulePath, productionRoot)) {
      process.stderr.write(`STATE_CONTEXT_WARNING: raf from ${codeRoot} uses working state ${statePath}; production tree is ${productionRoot}. Use a separate stand HOME with RAF_QA_HOME for develop.\n`);
    }
  }
  const tmpRoot = join(selectedHome, '.raf', 'tmp');
  const context: StateContext = Object.freeze({ mode, orchestratorRoot, codeRoot, homeDirectory: selectedHome,
    statePath, tmpRoot, tmuxSocketPath: join(tmpRoot, 'tmux', 'server.sock') });
  blockedPaths(context);
  return context;
}

export function verifyStateContext(context: StateContext): void {
  blockedPaths(context);
}

export function admitStateStore(context: StateContext): () => void {
  blockedPaths(context);
  return () => blockedPaths(context);
}

export function stateContextEnvironment(context: StateContext, inherited: Readonly<Record<string, string | undefined>>): Record<string, string | undefined> {
  const environment: Record<string, string | undefined> = { ...inherited, HOME: context.homeDirectory, RAF_HOME_DIRECTORY: context.homeDirectory,
    RAF_ORCHESTRATOR_ROOT: context.orchestratorRoot, RAF_STATE_DIRECTORY: dirname(context.statePath),
    RAF_SOCKET_PATH: join(dirname(context.statePath), 'service.sock') };
  delete environment.ALLOW_MIGRATIONS;
  if (context.mode === 'qa') {
    environment.RAF_QA_HOME = context.homeDirectory;
    delete environment.TMUX;
    delete environment.TMUX_PANE;
  } else delete environment.RAF_QA_HOME;
  return environment;

test('[module-origin-cost] extra published evidence and docs add zero guard file operations', async t => {
  const small = await fixture(t, 0);
  const large = await fixture(t, 24);
  const counter = operationCounter(t);
  const before = counter.measure(small.origin);
  const after = counter.measure(large.origin);
  assert.equal(before.result, small.generation);
  assert.equal(after.result, large.generation);
  assert.equal(after.operations.length, before.operations.length, 'one guard must not grow with excluded files or directory depth');
  for (const name of ['readFileSync', 'readdirSync', 'lstatSync']) {
    assert.equal(after.operations.filter(op => op.operation === name).length,
      before.operations.filter(op => op.operation === name).length, `${name} must be independent of evidence volume`);
  }
});

test('[module-origin-cost] one guard never traverses or reads proven non-runtime trees', async t => {
  const f = await fixture(t, 3);
  const counter = operationCounter(t);
  const observed = counter.measure(f.origin);
  assert.equal(observed.result, f.generation);
  const excluded = observed.operations.filter(op => ['evidence', 'docs'].some(tree =>
    op.path === join(f.generation, tree) || op.path.startsWith(join(f.generation, tree) + '/')));
  assert.deepEqual(excluded, [], 'even metadata/traversal of excluded descendants is forbidden');
});

test('[module-origin-cost] every successful guard rereads runtime bytes without a success cache', async t => {
  const f = await fixture(t);
  const counter = operationCounter(t);
  for (let i = 0; i < 2; i++) {
    const observed = counter.measure(f.origin);
    assert.equal(observed.result, f.generation);
    for (const path of Object.keys(runtimeInputs)) assert.ok(observed.operations.some(op =>
      op.path === join(f.generation, path) && op.operation.startsWith('readFile')), `guard ${i} must reread ${path}`);
  }
});

for (const path of Object.keys(runtimeInputs)) {
  for (const mutation of ['bytes', 'mode', 'delete'] as const) {
    test(`[module-origin-cost] ${mutation} of ${path} refuses immediately after a successful guard`, async t => {
      const f = await fixture(t);
      assert.equal(f.origin(), f.generation);
      const target = join(f.generation, path);
      if (mutation === 'bytes') fs.appendFileSync(target, '\nchanged\n');
      if (mutation === 'mode') fs.chmodSync(target, (fs.lstatSync(target).mode & 0o777) ^ 0o100);
      if (mutation === 'delete') fs.unlinkSync(target);
      assert.equal(f.origin(), undefined, `${mutation} must invalidate ${path}; no timer or cache may defer refusal`);
    });
  }
}

for (const path of ['src/new.unusual', 'src/new-package/package.json', 'scripts/new-child', 'dist/new.js',
  'node_modules/new-package/package.json', 'node_modules/origin-dep/new.payload', 'new-package/package.json']) {
  test(`[module-origin-cost] a new potential input ${path} cannot be trusted automatically`, async t => {
    const f = await fixture(t);
    assert.equal(f.origin(), f.generation);
    f.write(join(f.generation, path), '{}\n');
    assert.equal(f.origin(), undefined, 'enumerating only manifest files misses new resolution inputs');
  });
